-- Initial schema. Forward-only (no down migrations). IDs are UUID v7,
-- generated by the application (so primary keys are time-ordered and
-- `order by id` is chronological). JSON at the API boundary is camelCase;
-- columns here stay snake_case.
--
-- Length CHECKs mirror the limits in `hypercs_domain::constants`; change both
-- together (the API validates first, the CHECKs are the backstop).

create table users (
    id uuid primary key,
    username text not null
        check (char_length(username) between 3 and 32 and username ~ '^[A-Za-z0-9_-]+$'),
    display_name text not null check (char_length(display_name) between 1 and 50),
    email text not null check (char_length(email) <= 254),
    password_hash text not null,
    role text not null default 'member' check (role in ('admin', 'moderator', 'member')),
    first_name text check (char_length(first_name) <= 60),
    last_name text check (char_length(last_name) <= 60),
    location text check (char_length(location) <= 100),
    website text check (char_length(website) <= 200),
    about_me text check (char_length(about_me) <= 500),
    language text not null default 'en-US' check (language in ('en-US', 'de')),
    timezone text not null default 'UTC',
    notify_on_reply boolean not null default true,
    notify_on_quote boolean not null default true,
    show_online boolean not null default true,
    post_count integer not null default 0 check (post_count >= 0),
    created_at timestamptz not null default now()
);

-- Case-insensitive uniqueness; the original casing is stored.
create unique index users_username_lower_idx on users (lower(username));
create unique index users_email_lower_idx on users (lower(email));

-- Server-side sessions. Only a hash of the opaque cookie token is stored.
-- No IP address is kept; `user_agent` is a device hint for the sessions list.
create table sessions (
    id uuid primary key,
    user_id uuid not null references users (id) on delete cascade,
    token_hash text not null,
    csrf_token text not null,
    remember boolean not null default false,
    user_agent text check (char_length(user_agent) <= 255),
    expires_at timestamptz not null,
    last_seen_at timestamptz not null default now(),
    created_at timestamptz not null default now()
);

create unique index sessions_token_hash_idx on sessions (token_hash);
create index sessions_user_id_idx on sessions (user_id);
create index sessions_expires_at_idx on sessions (expires_at);
-- users-online query
create index sessions_last_seen_idx on sessions (last_seen_at);

create table categories (
    id uuid primary key,
    name text not null check (char_length(name) between 1 and 60),
    description text not null default '' check (char_length(description) <= 200),
    position integer not null,
    admin_only boolean not null default false,
    created_at timestamptz not null default now()
);

create index categories_position_idx on categories (position);

create table boards (
    id uuid primary key,
    category_id uuid not null references categories (id) on delete cascade,
    name text not null check (char_length(name) between 1 and 60),
    description text not null default '' check (char_length(description) <= 200),
    position integer not null,
    admin_only boolean not null default false,
    -- denormalized counters, maintained by the service layer in the same
    -- transaction as the change (repair tool: `hypercs-server recount`)
    topic_count integer not null default 0 check (topic_count >= 0),
    post_count integer not null default 0 check (post_count >= 0),
    last_post_id uuid,
    last_post_at timestamptz,
    created_at timestamptz not null default now()
);

create index boards_category_position_idx on boards (category_id, position);

create table topics (
    id uuid primary key,
    board_id uuid not null references boards (id) on delete cascade,
    title text not null check (char_length(title) between 3 and 120),
    slug text not null,
    author_id uuid not null references users (id) on delete cascade,
    -- The explicit marker for "the first post": deleting that post removes
    -- the topic (see the cascading FK below). Set when the topic is created.
    first_post_id uuid not null,
    pinned boolean not null default false,
    locked boolean not null default false,
    reply_count integer not null default 0 check (reply_count >= 0),
    view_count integer not null default 0 check (view_count >= 0),
    last_post_id uuid,
    last_post_at timestamptz not null,
    created_at timestamptz not null default now()
);

-- Board topic list: pinned first, then most recent activity.
create index topics_board_pinned_last_idx on topics (board_id, pinned desc, last_post_at desc);
-- Board "last post" lookup after deletes/moves.
create index topics_board_last_idx on topics (board_id, last_post_at desc);

create table posts (
    id uuid primary key,
    topic_id uuid not null references topics (id) on delete cascade,
    author_id uuid not null references users (id) on delete cascade,
    body text not null check (char_length(body) between 1 and 10000),
    edited_at timestamptz,
    edited_by uuid references users (id) on delete set null,
    created_at timestamptz not null default now()
);

-- Posts of a topic in order (UUID v7 ids are chronological).
create index posts_topic_id_idx on posts (topic_id, id);
-- Flood control / duplicate guard: the latest post of an author.
create index posts_author_created_idx on posts (author_id, created_at);

-- The circular references topics <-> posts are deferred so a topic and its
-- first post can be inserted in either order within one transaction.
-- Deleting the first post cascades to the topic (and so to all its posts).
alter table topics
    add constraint topics_first_post_fk foreign key (first_post_id)
        references posts (id) on delete cascade deferrable initially deferred;
alter table topics
    add constraint topics_last_post_fk foreign key (last_post_id)
        references posts (id) on delete set null deferrable initially deferred;
alter table boards
    add constraint boards_last_post_fk foreign key (last_post_id)
        references posts (id) on delete set null deferrable initially deferred;

-- Edit history: the body as it was *before* each edit.
create table post_revisions (
    id uuid primary key,
    post_id uuid not null references posts (id) on delete cascade,
    body text not null,
    edited_by uuid references users (id) on delete set null,
    created_at timestamptz not null default now()
);

create index post_revisions_post_idx on post_revisions (post_id, id);

-- News items are addressed by id; the slug is cosmetic and not unique.
create table news_items (
    id uuid primary key,
    title text not null check (char_length(title) between 1 and 120),
    slug text not null,
    body text not null check (char_length(body) <= 5000),
    author_id uuid references users (id) on delete set null,
    published_at timestamptz not null default now(),
    created_at timestamptz not null default now()
);

create index news_items_published_idx on news_items (published_at desc, id desc);

-- Homepage and terms-of-service content, one row per key.
create table cms_content (
    key text primary key,
    data jsonb not null,
    updated_at timestamptz not null default now()
);
